package insights

import (
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/charmbracelet/lipgloss"
	"golang.org/x/term"
)

// styles mirrors the pattern from status_style.go.
type styles struct {
	colorEnabled bool
	width        int

	green  lipgloss.Style
	red    lipgloss.Style
	yellow lipgloss.Style
	gray   lipgloss.Style
	bold   lipgloss.Style
	dim    lipgloss.Style
	cyan   lipgloss.Style
}

func newStyles(w io.Writer) styles {
	useColor := shouldUseColor(w)
	width := getTerminalWidth(w)

	s := styles{colorEnabled: useColor, width: width}
	if useColor {
		s.green = lipgloss.NewStyle().Foreground(lipgloss.Color("2"))
		s.red = lipgloss.NewStyle().Foreground(lipgloss.Color("1"))
		s.yellow = lipgloss.NewStyle().Foreground(lipgloss.Color("3"))
		s.gray = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
		s.bold = lipgloss.NewStyle().Bold(true)
		s.dim = lipgloss.NewStyle().Faint(true)
		s.cyan = lipgloss.NewStyle().Foreground(lipgloss.Color("6"))
	}
	return s
}

func (s styles) render(style lipgloss.Style, text string) string {
	if !s.colorEnabled {
		return text
	}
	return style.Render(text)
}

func shouldUseColor(w io.Writer) bool {
	if os.Getenv("NO_COLOR") != "" {
		return false
	}
	if f, ok := w.(*os.File); ok {
		return term.IsTerminal(int(f.Fd())) //nolint:gosec // G115: uintptr->int is safe for fd
	}
	return false
}

func getTerminalWidth(w io.Writer) int {
	if f, ok := w.(*os.File); ok {
		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
			return min(width, 80)
		}
	}
	return 60
}

// RenderReport writes the full insights report to the writer.
func RenderReport(w io.Writer, report InsightsReport) {
	s := newStyles(w)

	fmt.Fprintf(w, "\n%s\n", s.render(s.bold, "Entire Insights"))
	fmt.Fprintf(w, "%s\n\n", s.render(s.dim, "Period: "+report.Period))

	if len(report.Sessions) == 0 {
		fmt.Fprintln(w, "No sessions found for this period.")
		fmt.Fprintln(w, "Run some agent sessions, then try again.")
		return
	}

	// Session scores
	renderSessionScores(w, s, report.Sessions)

	// Trends
	if len(report.Trends) > 0 {
		fmt.Fprintln(w)
		renderTrends(w, s, report.Trends)
	}

	// Agent comparisons
	if len(report.Comparisons) > 0 {
		fmt.Fprintln(w)
		renderComparisons(w, s, report.Comparisons)
	}
}

func renderSessionScores(w io.Writer, s styles, scores []SessionScore) {
	fmt.Fprintf(w, "%s\n", sectionRule(s, "Session Scores"))

	for _, score := range scores {
		scoreColor := s.green
		if score.Overall < 50 {
			scoreColor = s.red
		} else if score.Overall < 70 {
			scoreColor = s.yellow
		}

		fmt.Fprintf(w, "\n  %s  %s  %s\n",
			s.render(scoreColor, fmt.Sprintf("%.1f", score.Overall)),
			s.render(s.bold, string(score.Agent)),
			s.render(s.dim, score.SessionID),
		)

		fmt.Fprintf(w, "    Token Efficiency: %-6.0f  First-Pass: %-6.0f  Friction: %-6.0f  Focus: %.0f\n",
			score.Breakdown.TokenEfficiency,
			score.Breakdown.FirstPassSuccess,
			score.Breakdown.FrictionScore,
			score.Breakdown.FocusScore,
		)

		fmt.Fprintf(w, "    %s tokens  %s turns  %s files  %s friction\n",
			s.render(s.cyan, formatTokenCount(score.TokensUsed)),
			s.render(s.cyan, fmt.Sprintf("%d", score.TurnCount)),
			s.render(s.cyan, fmt.Sprintf("%d", score.FilesCount)),
			s.render(s.cyan, fmt.Sprintf("%d", score.FrictionCount)),
		)
	}
}

func renderTrends(w io.Writer, s styles, trends []Trend) {
	fmt.Fprintf(w, "%s\n\n", sectionRule(s, "Trends"))

	for _, t := range trends {
		arrow := "→"
		arrowStyle := s.gray
		switch t.Direction {
		case "improving":
			arrow = "↑"
			arrowStyle = s.green
		case "declining":
			arrow = "↓"
			arrowStyle = s.red
		}

		label := strings.ReplaceAll(t.Metric, "_", " ")
		fmt.Fprintf(w, "  %s %s %s\n",
			s.render(arrowStyle, arrow),
			label,
			s.render(s.dim, fmt.Sprintf("(%.1f%%)", t.ChangePercent)),
		)
	}
}

func renderComparisons(w io.Writer, s styles, comparisons []AgentComparison) {
	fmt.Fprintf(w, "%s\n\n", sectionRule(s, "Agent Comparison"))

	for _, c := range comparisons {
		fmt.Fprintf(w, "  %s  %s (%d sessions)\n",
			s.render(s.bold, fmt.Sprintf("%.1f", c.AvgScore)),
			s.render(s.bold, string(c.Agent)),
			c.SessionCount,
		)
		fmt.Fprintf(w, "    avg %s tokens  %.1f turns  %.1f friction\n",
			formatTokenCount(c.AvgTokens), c.AvgTurns, c.AvgFriction,
		)
		if c.TopStrength != "" {
			fmt.Fprintf(w, "    %s %s  %s %s\n",
				s.render(s.green, "+"),
				c.TopStrength,
				s.render(s.red, "-"),
				c.TopWeakness,
			)
		}
	}
}

func sectionRule(s styles, label string) string {
	prefix := "── "
	content := label + " "
	usedWidth := len([]rune(prefix)) + len([]rune(content))
	trailing := s.width - usedWidth
	if trailing < 1 {
		trailing = 1
	}

	var b strings.Builder
	b.WriteString(s.render(s.dim, "── "))
	b.WriteString(s.render(s.dim, label))
	b.WriteString(" ")
	b.WriteString(s.render(s.dim, strings.Repeat("─", trailing)))
	return b.String()
}

func formatTokenCount(n int) string {
	if n < 1000 {
		return fmt.Sprintf("%d", n)
	}
	f := float64(n) / 1000.0
	s := fmt.Sprintf("%.1f", f)
	s = strings.TrimSuffix(s, ".0")
	return s + "k"
}
