package cli

import (
	"context"
	"fmt"
	"io"

	cpkg "github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/insights"
	"github.com/spf13/cobra"
)

func newInsightsCmd() *cobra.Command {
	var (
		last  int
		agent string
	)

	cmd := &cobra.Command{
		Use:   "insights",
		Short: "Show session quality scores, trends, and agent comparisons",
		Long: `Analyze your recent agent sessions to understand quality trends,
token efficiency, and friction patterns across agents.

Examples:
  entire insights              # Last 10 sessions
  entire insights --last 30    # Last 30 sessions
  entire insights --agent "Claude Code"  # Filter by agent`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
				return nil
			}
			return runInsights(cmd.Context(), cmd.OutOrStdout(), last, agent)
		},
	}

	cmd.Flags().IntVar(&last, "last", 10, "Number of recent sessions to analyze")
	cmd.Flags().StringVar(&agent, "agent", "", "Filter by agent name (e.g., 'Claude Code', 'Cursor')")

	return cmd
}

func runInsights(ctx context.Context, w io.Writer, last int, agentFilter string) error {
	repo, err := openRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	store := cpkg.NewGitStore(repo)
	committed, err := store.ListCommitted(ctx)
	if err != nil {
		return fmt.Errorf("failed to list checkpoints: %w", err)
	}

	// Collect scores from committed checkpoints
	var scores []insights.SessionScore
	for _, cp := range committed {
		for _, sp := range cp.Sessions {
			content, err := store.ReadSessionContent(ctx, cp.CheckpointID, sp)
			if err != nil {
				continue
			}

			if agentFilter != "" && string(content.Metadata.Agent) != agentFilter {
				continue
			}

			raw := insights.AggregateSession(&content.Metadata)
			score := insights.ScoreSession(raw)
			scores = append(scores, score)
		}
	}

	// Limit to most recent N
	if len(scores) > last {
		scores = scores[len(scores)-last:]
	}

	// Compute trends and comparisons
	trends := insights.ComputeTrends(scores)
	comparisons := insights.ComputeAgentComparisons(scores)

	report := insights.InsightsReport{
		Sessions:    scores,
		Trends:      trends,
		Comparisons: comparisons,
		Period:      fmt.Sprintf("last %d sessions", last),
	}

	insights.RenderReport(w, report)
	return nil
}
