package improve

import (
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
)

// SessionSummaryData pairs a session ID with its summary.
type SessionSummaryData struct {
	SessionID string
	Summary   *checkpoint.Summary
}

// PatternAnalysis contains extracted patterns from multiple sessions.
type PatternAnalysis struct {
	RepeatedFriction  []FrictionPattern
	RepoLearnings     []string
	WorkflowLearnings []string
	CodeLearnings     []checkpoint.CodeLearning
	OpenItems         []string
	SessionCount      int
}

// FrictionPattern represents a recurring friction theme.
type FrictionPattern struct {
	Theme    string   // Normalized theme description
	Count    int      // Number of sessions with this friction
	Examples []string // Raw friction strings from sessions
	Sessions []string // Session IDs where this occurred
}

// AnalyzePatterns extracts recurring patterns from session summaries.
func AnalyzePatterns(summaries []SessionSummaryData) PatternAnalysis {
	analysis := PatternAnalysis{
		SessionCount: len(summaries),
	}

	// Collect all friction points with deduplication by theme
	frictionIndex := make(map[string]*FrictionPattern)
	repoLearningsSet := make(map[string]bool)
	workflowSet := make(map[string]bool)

	for _, sd := range summaries {
		if sd.Summary == nil {
			continue
		}

		// Analyze friction
		for _, f := range sd.Summary.Friction {
			theme := normalizeFriction(f)
			if existing, ok := frictionIndex[theme]; ok {
				existing.Count++
				existing.Examples = append(existing.Examples, f)
				existing.Sessions = append(existing.Sessions, sd.SessionID)
			} else {
				frictionIndex[theme] = &FrictionPattern{
					Theme:    theme,
					Count:    1,
					Examples: []string{f},
					Sessions: []string{sd.SessionID},
				}
			}
		}

		// Collect learnings
		for _, l := range sd.Summary.Learnings.Repo {
			if !repoLearningsSet[l] {
				repoLearningsSet[l] = true
				analysis.RepoLearnings = append(analysis.RepoLearnings, l)
			}
		}
		for _, l := range sd.Summary.Learnings.Workflow {
			if !workflowSet[l] {
				workflowSet[l] = true
				analysis.WorkflowLearnings = append(analysis.WorkflowLearnings, l)
			}
		}
		analysis.CodeLearnings = append(analysis.CodeLearnings, sd.Summary.Learnings.Code...)
		analysis.OpenItems = append(analysis.OpenItems, sd.Summary.OpenItems...)
	}

	// Only include friction that appears 2+ times as "repeated"
	for _, fp := range frictionIndex {
		if fp.Count >= 2 {
			analysis.RepeatedFriction = append(analysis.RepeatedFriction, *fp)
		}
	}

	return analysis
}

// normalizeFriction extracts a normalized theme from a friction description.
// Groups similar friction like "lint error" and "linter failed" under the same theme.
func normalizeFriction(friction string) string {
	lower := strings.ToLower(friction)

	// Common friction theme keywords
	themes := []struct {
		keywords []string
		theme    string
	}{
		{[]string{"lint", "linter", "golangci"}, "linting issues"},
		{[]string{"import", "missing import"}, "missing imports"},
		{[]string{"test", "failing test", "test fail"}, "test failures"},
		{[]string{"type", "type error", "type mismatch"}, "type errors"},
		{[]string{"compile", "build", "syntax"}, "compilation errors"},
		{[]string{"format", "gofmt", "formatting"}, "formatting issues"},
		{[]string{"permission", "access", "auth"}, "permission issues"},
		{[]string{"timeout", "slow", "hang"}, "performance issues"},
		{[]string{"retry", "retried", "again"}, "required retries"},
	}

	for _, t := range themes {
		for _, kw := range t.keywords {
			if strings.Contains(lower, kw) {
				return t.theme
			}
		}
	}

	// If no known theme, use the first 50 chars as a unique-ish key
	if len(friction) > 50 {
		return strings.ToLower(friction[:50])
	}
	return strings.ToLower(friction)
}
