	Status       string    `json:"status"` // "pending", "accepted", "rejected", "expired"
	CreatedAt    time.Time `json:"created_at"`
	ResolvedAt   *time.Time `json:"resolved_at,omitempty"`
	ImpactBefore *float64  `json:"impact_before,omitempty"` // Avg score before acceptance
	ImpactAfter  *float64  `json:"impact_after,omitempty"`  // Avg score after acceptance
}
