```go
package evolve

import (
	"fmt"
	"time"
)

// Tracker manages the lifecycle of improvement suggestions.
type Tracker struct {
	Records map[string]*SuggestionRecord
}

// NewTracker creates a new suggestion tracker.
func NewTracker() *Tracker {
	return &Tracker{
		Records: make(map[string]*SuggestionRecord),
	}
}

// AddSuggestion registers a new suggestion.
func (t *Tracker) AddSuggestion(rec SuggestionRecord) {
	if rec.CreatedAt.IsZero() {
		rec.CreatedAt = time.Now()
	}
	t.Records[rec.ID] = &rec
}

// Get returns a suggestion by ID, or nil if not found.
func (t *Tracker) Get(id string) *SuggestionRecord {
	return t.Records[id]
}

// Accept marks a suggestion as accepted.
func (t *Tracker) Accept(id string) error {
	rec, ok := t.Records[id]
	if !ok {
		return fmt.Errorf("suggestion %q not found", id)
	}
	rec.Status = "accepted"
	now := time.Now()
	rec.ResolvedAt = &now
	return nil
}

// Reject marks a suggestion as rejected.
func (t *Tracker) Reject(id string) error {
	rec, ok := t.Records[id]
	if !ok {
		return fmt.Errorf("suggestion %q not found", id)
	}
	rec.Status = "rejected"
	now := time.Now()
	rec.ResolvedAt = &now
	return nil
}

// MeasureImpact calculates the before/after score impact of a suggestion.
func (t *Tracker) MeasureImpact(id string, scoresBefore, scoresAfter []float64) *SuggestionRecord {
	rec, ok := t.Records[id]
	if !ok {
		return nil
	}

	if len(scoresBefore) > 0 {
		avg := average(scoresBefore)
		rec.ImpactBefore = &avg
	}
	if len(scoresAfter) > 0 {
		avg := average(scoresAfter)
		rec.ImpactAfter = &avg
	}

	return rec
}

// Pending returns all suggestions with "pending" status.
func (t *Tracker) Pending() []SuggestionRecord {
	var pending []SuggestionRecord
	for _, rec := range t.Records {
		if rec.Status == "pending" {
			pending = append(pending, *rec)
		}
	}
	return pending
}

func average(vals []float64) float64 {
	if len(vals) == 0 {
		return 0
	}
	var sum float64
	for _, v := range vals {
		sum += v
	}
	return sum / float64(len(vals))
}
```

