package improve

import (
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/charmbracelet/lipgloss"
	"golang.org/x/term"
)

type diffStyles struct {
	colorEnabled bool
	width        int

	green  lipgloss.Style
	red    lipgloss.Style
	yellow lipgloss.Style
	bold   lipgloss.Style
	dim    lipgloss.Style
	cyan   lipgloss.Style
}

func newDiffStyles(w io.Writer) diffStyles {
	useColor := false
	if os.Getenv("NO_COLOR") == "" {
		if f, ok := w.(*os.File); ok {
			useColor = term.IsTerminal(int(f.Fd())) //nolint:gosec // G115
		}
	}

	width := 60
	if f, ok := w.(*os.File); ok {
		if w, _, err := term.GetSize(int(f.Fd())); err == nil && w > 0 { //nolint:gosec // G115
			width = min(w, 80)
		}
	}

	s := diffStyles{colorEnabled: useColor, width: width}
	if useColor {
		s.green = lipgloss.NewStyle().Foreground(lipgloss.Color("2"))
		s.red = lipgloss.NewStyle().Foreground(lipgloss.Color("1"))
		s.yellow = lipgloss.NewStyle().Foreground(lipgloss.Color("3"))
		s.bold = lipgloss.NewStyle().Bold(true)
		s.dim = lipgloss.NewStyle().Faint(true)
		s.cyan = lipgloss.NewStyle().Foreground(lipgloss.Color("6"))
	}
	return s
}

func (s diffStyles) render(style lipgloss.Style, text string) string {
	if !s.colorEnabled {
		return text
	}
	return style.Render(text)
}

// RenderImprovementReport writes the improvement report to the writer.
func RenderImprovementReport(w io.Writer, report ImprovementReport) {
	s := newDiffStyles(w)

	fmt.Fprintf(w, "\n%s\n", s.render(s.bold, "Entire Improve"))
	fmt.Fprintf(w, "%s\n\n",
		s.render(s.dim, fmt.Sprintf("Analyzed %d sessions | %d friction points | %d patterns found",
			report.SessionsUsed, report.FrictionTotal, report.PatternsFound)))

	if len(report.Suggestions) == 0 {
		fmt.Fprintln(w, "No suggestions found. Your context files look good!")
		return
	}

	// Context file status
	if len(report.ContextFiles) > 0 {
		fmt.Fprintf(w, "%s\n", renderSectionRule(s, "Context Files"))
		for _, cf := range report.ContextFiles {
			status := s.render(s.red, "missing")
			if cf.Exists {
				status = s.render(s.green, fmt.Sprintf("%d bytes", cf.SizeBytes))
			}
			fmt.Fprintf(w, "  %s  %s\n", string(cf.Type), status)
		}
		fmt.Fprintln(w)
	}

	// Suggestions
	fmt.Fprintf(w, "%s\n", renderSectionRule(s, fmt.Sprintf("Suggestions (%d)", len(report.Suggestions))))

	for i, sug := range report.Suggestions {
		priorityStyle := s.dim
		switch sug.Priority {
		case "high":
			priorityStyle = s.red
		case "medium":
			priorityStyle = s.yellow
		}

		fmt.Fprintf(w, "\n  %s %s  %s\n",
			s.render(s.bold, fmt.Sprintf("%d.", i+1)),
			s.render(s.bold, sug.Title),
			s.render(priorityStyle, sug.Priority),
		)
		fmt.Fprintf(w, "     %s → %s\n", sug.Category, string(sug.FileType))
		fmt.Fprintf(w, "     %s\n", sug.Description)

		// Render diff with colors
		if sug.Diff != "" {
			fmt.Fprintln(w)
			renderDiff(w, s, sug.Diff)
		}
	}
	fmt.Fprintln(w)
}

func renderDiff(w io.Writer, s diffStyles, diff string) {
	lines := strings.Split(diff, "\n")
	for _, line := range lines {
		switch {
		case strings.HasPrefix(line, "+"):
			fmt.Fprintf(w, "     %s\n", s.render(s.green, line))
		case strings.HasPrefix(line, "-"):
			fmt.Fprintf(w, "     %s\n", s.render(s.red, line))
		case strings.HasPrefix(line, "@@"):
			fmt.Fprintf(w, "     %s\n", s.render(s.cyan, line))
		default:
			fmt.Fprintf(w, "     %s\n", s.render(s.dim, line))
		}
	}
}

func renderSectionRule(s diffStyles, label string) string {
	prefix := "── "
	content := label + " "
	usedWidth := len([]rune(prefix)) + len([]rune(content))
	trailing := s.width - usedWidth
	if trailing < 1 {
		trailing = 1
	}

	var b strings.Builder
	b.WriteString(s.render(s.dim, "── "))
	b.WriteString(s.render(s.dim, label))
	b.WriteString(" ")
	b.WriteString(s.render(s.dim, strings.Repeat("─", trailing)))
	return b.String()
}

