package evolve

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
)

const stateFile = ".entire/evolve-state.json"

// LoadState reads the evolution state from .entire/evolve-state.json.
// Returns a zero-value State if the file doesn't exist.
func LoadState(repoRoot string) (*State, error) {
	path := filepath.Join(repoRoot, stateFile)
	data, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return &State{}, nil
		}
		return nil, err
	}
	var state State
	if err := json.Unmarshal(data, &state); err != nil {
		return &State{}, nil // Corrupt file → fresh state
	}
	return &state, nil
}

// SaveState writes the evolution state to .entire/evolve-state.json.
func SaveState(repoRoot string, state *State) error {
	path := filepath.Join(repoRoot, stateFile)
	data, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}
